--liquibase formatted sql

-- Sample accounts to practise the account review on, applied only when the demo context
-- is requested, which the local profile does and the tests do not (see docs/adr/0018). They
-- have no Keycloak account, so nobody can sign in as them; they are only there to be
-- reviewed. They cover the states a reviewer sees: signed in recently and long ago, never
-- signed in, long unused, suspended for different reasons, and accounts already removed.
-- The review is switched on so the scheduler creates a task covering every account soon after
-- the application starts. The date arithmetic is H2's, which the local profile uses.

--changeset app:014-development-review-sample-data context:@demo
UPDATE app_setting SET setting_value = 'true' WHERE name = 'review.enabled';
